var i=73;var a=[{id:`cooking-073-01`,theoryId:73,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`What distinguishes shallow-frying from deep-frying?`,ua:`Чим смаження у невеликій кількості олії відрізняється від фритюру?`},explanation:{en:`In shallow-frying food contacts hot oil on one side at a time.`,ua:`За неглибокого смаження продукт контактує з гарячою олією переважно з одного боку.`},options:[{id:`a`,text:{en:`Food is only partly surrounded by oil and usually turned`,ua:`Олія покриває продукт частково, тож його зазвичай перевертають`}},{id:`b`,text:{en:`Shallow-frying uses no heat`,ua:`Смаження з невеликою кількістю олії не потребує нагріву`}},{id:`c`,text:{en:`Deep-frying always requires a dry pan`,ua:`Фритюр завжди потребує сухої сковороди`}}],answer:{optionIds:[`a`]}},{id:`cooking-073-02`,theoryId:73,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Turning a cutlet can help even the browning on both sides.`,ua:`Перевертання відбивної може забезпечити рівномірне підрум’янення з обох боків.`},explanation:{en:`Both surfaces need exposure to hot oil for similar browning.`,ua:`Обидві поверхні мають контактувати з гарячою олією для подібного кольору.`},answer:{value:!0}},{id:`cooking-073-03`,theoryId:73,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match the frying observation with the response.`,ua:`Поєднайте ознаку смаження з доречною дією.`},explanation:{en:`Heat, surface moisture and batch size all affect frying.`,ua:`Нагрів, поверхнева волога та розмір порції впливають на смаження.`},leftItems:[{id:`l1`,text:{en:`Crust browns too fast`,ua:`Скоринка темніє надто швидко`}},{id:`l2`,text:{en:`Oil splatters from wet food`,ua:`Олія розбризкується від мокрого продукту`}},{id:`l3`,text:{en:`Food crowds the pan`,ua:`Продукти переповнюють сковороду`}}],rightItems:[{id:`r3`,text:{en:`Cook in batches`,ua:`Готувати порціями`}},{id:`r2`,text:{en:`Dry surface before adding`,ua:`Обсушити поверхню перед додаванням`}},{id:`r1`,text:{en:`Reduce heat`,ua:`Зменшити нагрів`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-073-04`,theoryId:73,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`A breaded cutlet browns before the center cooks. What is appropriate?`,ua:`Панірована відбивна темніє раніше, ніж готується середина. Що доречно?`},explanation:{en:`Color and internal doneness depend on different heat-transfer processes.`,ua:`Колір і внутрішня готовність залежать від різних процесів теплопередачі.`},options:[{id:`a`,text:{en:`Reduce heat, then verify the center with a thermometer`,ua:`Зменшити жар та перевірити середину термометром`}},{id:`b`,text:{en:`Turn heat to maximum`,ua:`Збільшити жар до максимуму`}},{id:`c`,text:{en:`Assume a golden crust guarantees safety`,ua:`Вважати золотисту скоринку гарантією безпеки`}}],answer:{optionIds:[`a`]}},{id:`cooking-073-05`,theoryId:73,type:`find_mistake`,difficulty:`intermediate`,safetyCritical:!0,question:{en:`Which action raises splatter risk?`,ua:`Яка дія збільшує ризик розбризкування олії?`},explanation:{en:`Water contacting hot oil can cause violent splattering.`,ua:`Контакт води з гарячою олією може спричинити сильне розбризкування.`},options:[{id:`a`,text:{en:`Gently lower food away from yourself`,ua:`Обережно опускати продукт від себе`}},{id:`b`,text:{en:`Use utensils suited to hot oil`,ua:`Використовувати інструменти для гарячої олії`}},{id:`c`,text:{en:`Drop a dripping-wet cutlet from a height`,ua:`Кинути мокру відбивну з висоти`}}],answer:{optionIds:[`c`]}}];var n={theoryId:73,exercises:a};export{n as default,a as exercises,i as theoryId};